<script setup lang="ts">
import {computed} from 'vue';
const props=defineProps<{schema:any,modelValue:Record<string,any>,prefix?:string,firstField?:string}>();
const labels:Record<string,string>={path:'串口路径',baud_rate:'波特率',data_bits:'数据位',parity:'校验',stop_bits:'停止位',timeout_ms:'通信超时',address:'从机地址',max_voltage:'设备电压上限',max_current:'设备电流上限',voltage:'电压',current_limit:'电流限值',enabled:'输出开关'};
const fields=computed(()=>Object.entries<any>(props.schema?.properties||{}).sort(([a],[b])=>a===props.firstField?-1:b===props.firstField?1:0));
const emit=defineEmits(['update:modelValue']);
function set(key:string,value:any){const next={...props.modelValue};if(value===''){delete next[key]}else{next[key]=value};emit('update:modelValue',next)}
</script>
<template><div class="schema-fields"><label v-for="[key,field] in fields" :key="key" :for="(prefix||'field')+'-'+key"><span>{{labels[String(key)]||field.description||key}} <small v-if="field.unit">{{field.unit}}</small><span v-if="schema.required?.includes(key)" class="required"> *</span></span><select v-if="field.type==='boolean'" :id="(prefix||'field')+'-'+key" :value="modelValue[key]===undefined?'':String(modelValue[key])" :required="schema.required?.includes(key)" @change="set(String(key),($event.target as HTMLSelectElement).value===''?'':($event.target as HTMLSelectElement).value==='true')"><option value="">请选择</option><option value="false">关闭 / false</option><option value="true">开启 / true</option></select><select v-else-if="field.enum" :id="(prefix||'field')+'-'+key" :value="modelValue[key]??''" @change="set(String(key),($event.target as HTMLSelectElement).value)"><option v-for="v in field.enum" :key="String(v)" :value="v">{{v}}</option></select><input v-else :id="(prefix||'field')+'-'+key" :type="['number','integer'].includes(field.type)?'number':'text'" :step="field.multipleOf|| (field.type==='integer'?1:'any')" :min="field.minimum" :max="field.maximum" :value="modelValue[key]??''" :required="schema.required?.includes(key)" @input="set(String(key),($event.target as HTMLInputElement).value===''?'':(['number','integer'].includes(field.type)?Number(($event.target as HTMLInputElement).value):($event.target as HTMLInputElement).value))"><small v-if="field.minimum!==undefined||field.maximum!==undefined" class="muted">范围 {{field.minimum??'不限'}} 至 {{field.maximum??'不限'}}；精度 {{field.multipleOf??'不限'}}</small></label></div></template>
